ranges=['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']
print('\n[Task] Check current contents and fill colors (RGB) for target ranges')

def cell_fill_rgb(cell):
    fill=cell.fill
    if not fill:
        return None
    fg=fill.fgColor
    if not fg:
        return None
    if fg.type=='rgb':
        return fg.rgb
    if fg.type=='indexed':
        return f'indexed:{fg.indexed}'
    if fg.type=='theme':
        return f'theme:{fg.theme} tint:{fg.tint}'
    return str(fg)

